import React, { useState, useEffect } from 'react';
import axios from 'axios';
import { Container, Row, Col, Card, Spinner } from 'react-bootstrap';

const UpcomingEvents = () => {
  const [events, setEvents] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);

  useEffect(() => {
    const fetchEvents = async () => {
      try {
        const response = await axios.get('/api/events/upcoming', {
          headers: { Authorization: `Bearer ${localStorage.getItem('authToken')}` },
        });
        setEvents(response.data);
      } catch (error) {
        console.error('Error fetching events:', error);
        setError('Failed to load events. Please try again.');
      } finally {
        setLoading(false);
      }
    };
    fetchEvents();
  }, []);

  return (
    <Container className="mt-5">
      <h2 className="text-center mb-4">Upcoming Events</h2>

      {loading ? (
        <div className="text-center">
          <Spinner animation="border" variant="info" />
        </div>
      ) : error ? (
        <p className="text-danger text-center">{error}</p>
      ) : events.length > 0 ? (
        <Row>
          {events.map((event) => (
            <Col key={event._id} md={4} className="mb-4">
              <Card className="shadow-lg card-hover">
                {event.image && (
                  <Card.Img variant="top" src={event.image} alt={event.title} />
                )}
                <Card.Body>
                  <Card.Title className="fw-bold">{event.title}</Card.Title>
                  <Card.Text>{event.description}</Card.Text>
                  <Card.Text>
                    <strong>Date:</strong> {new Date(event.date).toLocaleDateString()}
                  </Card.Text>
                  <Card.Text>
                    <strong>Location:</strong> {event.location}
                  </Card.Text>
                  <Card.Text>
                    <strong>Entry Fees:</strong> {event.entryFees ? `₹${event.entryFees}` : 'Free'}
                  </Card.Text>
                </Card.Body>
              </Card>
            </Col>
          ))}
        </Row>
      ) : (
        <p className="text-center">No upcoming events available.</p>
      )}
    </Container>
  );
};

export default UpcomingEvents;
